import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const k=JSON.parse('{"title":"Module 3 · The town currency","description":"","frontmatter":{},"headers":[],"relativePath":"modules/03-town-token.md","filePath":"modules/03-town-token.md","lastUpdated":1790431304000}'),n={name:"modules/03-town-token.md"};function o(h,e,r,l,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="module-3-·-the-town-currency" tabindex="-1">Module 3 · The town currency <a class="header-anchor" href="#module-3-·-the-town-currency" aria-label="Permalink to &quot;Module 3 · The town currency&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contracts</strong></td><td><code>TownToken.sol</code>, <code>TownBank.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Bank</td></tr><tr><td><strong>Standard</strong></td><td>ERC-20</td></tr><tr><td><strong>Stamp</strong></td><td>Module 3</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>Trustville needs money — something to pay rent with, escrow, bid, donate, lend. And the first question anyone should ask of any currency is: <strong>who can create more of it, and what stops them?</strong></p><p>That question has a bad answer in most student token projects. The deployer holds a <code>mint</code> function, and the honest description of the token is &quot;worth whatever the deployer feels like&quot;.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>An ordinary ERC-20 with a hard supply cap, where the right to mint is held by a <strong>contract</strong> rather than a person.</p><p><code>TownBank</code> holds <code>MINTER_ROLE</code>. It mints in exactly one circumstance: a registered resident claims their welcome grant, once. No human address can mint, including the town admin, including the deployer. The rule is in the code, and anyone can check it in thirty seconds on the explorer.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>ERC-20.</strong> The fungible token standard: <code>balanceOf</code>, <code>transfer</code>, <code>approve</code>, <code>transferFrom</code>, <code>allowance</code>, plus <code>Transfer</code> and <code>Approval</code> events. Every wallet and exchange already speaks it, which is the entire reason to use a standard.</p><p><strong>Decimals.</strong> ERC-20 balances are integers. <code>decimals() = 18</code> means the contract stores <code>1000000000000000000</code> and interfaces display <code>1.0</code>. <strong>The chain has no fractions.</strong> Every &quot;1.5 TVD&quot; you see is a display convention over an integer, and forgetting that produces the commonest bug in dApp frontends.</p><p><strong>Allowance.</strong> <code>transferFrom</code> lets a contract move your tokens, but only up to the amount you approved. That is why paying into escrow is two transactions: <code>approve</code>, then the action. Users find it confusing and it is not going away — it is what stops a contract emptying your wallet.</p><p><strong>Role held by a contract.</strong> <code>MINTER_ROLE</code> on an address that is a contract means the minting rule is code, not discretion. This is the single most important idea in the module.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><strong>TownToken</strong> — ERC-20 plus two things:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> immutable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxSupply;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> mint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> onlyRole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MINTER_ROLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> maxSupply </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> totalSupply</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (amount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MaxSupplyExceeded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(amount, remaining);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    _mint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(to, amount);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>immutable</code> means <code>maxSupply</code> is fixed at deployment and stored in the bytecode, not in storage — cheaper to read, and impossible to change afterwards even by the admin. The cap is a property of the contract, not a setting.</p><p>Anyone may <code>burn</code> their own tokens. Nobody may burn anyone else&#39;s.</p><p><strong>TownBank</strong> — the only minter:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> claimWelcomeGrant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">registry.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isResident</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NotAResident</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (hasClaimed[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AlreadyClaimed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    hasClaimed[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    token.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, grantAmount);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ... stamps module 3</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Five lines that define the monetary policy of the town. The admin can change <code>grantAmount</code> for future claims, but cannot mint directly and cannot make anyone claim twice.</p><p><strong>Checks-effects-interactions.</strong> Notice <code>hasClaimed</code> is set <em>before</em> <code>token.mint</code> is called. The state change comes first, the external call second. That ordering is what makes reentrancy attacks fail, and it is worth forming the habit here where nothing is at stake.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p>Look at who can mint, on the live contract:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cast</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $TOKEN </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;hasRole(bytes32,address)(bool)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cast</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keccak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;MINTER_ROLE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) $TOWN_ADMIN </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">--rpc-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://eth.didlab.org</span></span></code></pre></div><p><code>false</code>. The town admin — who deployed everything, who arbitrates disputes, who issues certificates — cannot create a single TVD.</p><p>That is not politeness. <code>DeployTown.s.sol</code> grants <code>MINTER_ROLE</code> to the Bank contract and nothing else, then renounces its own admin rights and <strong>asserts</strong> the result, so a botched handover fails the deployment rather than shipping quietly.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Claim your welcome grant at the Bank.</li><li>On the explorer, open the transaction. Two events: <code>Transfer</code> from the zero address (which is what minting looks like) and <code>WelcomeGrantClaimed</code>.</li><li>Call <code>totalSupply()</code> and <code>maxSupply()</code>. Note the headroom.</li><li>Ask who holds <code>MINTER_ROLE</code>. It is an address — look it up. It is the Bank.</li><li>Claim again. <code>AlreadyClaimed</code>.</li><li>Send some TVD to a classmate and watch the <code>Transfer</code> event.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Transfer(from: 0x0000…0000, to: 0x…, value: 1000000000000000000000)</span></span>
<span class="line"><span>WelcomeGrantClaimed(resident: 0x…, amount: 1000000000000000000000)</span></span>
<span class="line"><span>Stamped(tokenId: 1, moduleId: 3, by: 0x…)</span></span></code></pre></div><p>Minting is a <code>Transfer</code> from the zero address; burning is a transfer <em>to</em> it. The ERC-20 standard has no separate mint event, which is why block explorers show supply changes as transfers from nowhere.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>For points inside one application — loyalty points, game currency, course credits — a database column is better in every way: free, instant, private, reversible.</p><p>An ERC-20 earns its place when the token must be <strong>usable by software you did not write</strong>. Every wallet displays it, every exchange can list it, and any contract can accept it as payment without asking permission. Trustville&#39;s escrow, auction, rent, insurance and lending modules all take TVD without the token contract knowing they exist.</p><p>That composability is the real product. It is also why a mistake in a token contract is permanent in a way a database migration is not.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>A capped supply does not create value.</strong> TVD is worth nothing; scarcity is not worth.</li><li><strong>The cap does not stop concentration.</strong> One address could hold everything.</li><li><strong>Code does not stop policy.</strong> The admin can set the grant to a billion for future claimants. The cap binds; the rate does not.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Handing <code>MINTER_ROLE</code> to a person.</strong> The commonest flaw in student token projects, and the one that makes the token meaningless.</li><li><strong>Assuming 18 decimals everywhere.</strong> USDC uses 6. Always read <code>decimals()</code>.</li><li><strong>Float arithmetic in the frontend.</strong> <code>parseUnits</code> and <code>formatUnits</code>, never <code>Number(x) * 1e18</code>, which silently loses precision above 2^53.</li><li><strong>Forgetting the approve step.</strong> Users see a transaction they did not expect and assume something is wrong.</li><li><strong>Infinite approvals for convenience.</strong> Common in production, and it means a bug in that contract can take everything.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Who holds <code>MINTER_ROLE</code>? Is every holder a contract?</li><li>[ ] Can the admin grant <code>MINTER_ROLE</code> to themselves? What would stop them?</li><li>[ ] Is <code>maxSupply</code> enforced on every mint path?</li><li>[ ] Can the welcome grant be claimed twice — from the same address, or by re-registering?</li><li>[ ] Does any contract hold an unnecessary infinite allowance?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Make <code>setGrantAmount</code> callable only by the DAO from module 12, so monetary policy needs a vote. Then look at what governance costs in delay.</li><li>Add a faucet that tops residents up with a cooldown, and work out what stops someone draining it with new addresses. (<code>GrainToken</code> in module 15 does exactly this — compare.)</li><li>Add <code>ERC20Permit</code> so approvals can be signed off-chain instead of costing a transaction. Note that module 12&#39;s <code>VoteToken</code> already inherits it.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://eips.ethereum.org/EIPS/eip-20" target="_blank" rel="noreferrer">ERC-20</a></li><li><a href="https://docs.openzeppelin.com/contracts/5.x/erc20" target="_blank" rel="noreferrer">OpenZeppelin ERC20</a></li><li><a href="https://eips.ethereum.org/EIPS/eip-2612" target="_blank" rel="noreferrer">ERC-2612 Permit</a></li></ul><p><strong>Next:</strong> <a href="./04-product-provenance">Module 4 · Product provenance →</a></p>`,47)])])}const g=a(n,[["render",o]]);export{k as __pageData,g as default};
